def find_smallest_number(numbers):
    # Initialize the first element as the smallest
    smallest = numbers[0]

    # Iterate over all elements to find the smallest one
    for num in numbers:
        if num < smallest:
            smallest = num

    return smallest

# Read input from user and store in a list
numbers = []
while True:
    try:
        entry = input(""Enter a floating-point number (or 'done' to finish): "")

        # Break the loop when user inputs 'done'
        if entry.lower() == 'done':
            break

        # Convert the input to float and add it to the list
        numbers.append(float(entry))
    except ValueError:
        print(""Please enter a valid floating-point number or 'done'."")

# Ensure there are numbers in the list before proceeding
if numbers:
    smallest = find_smallest_number(numbers)
    print(f""The smallest number is: {smallest}"")
else:
    print(""No numbers were entered."")
