import random

class EnhancedRandomGenerator:
    def __init__(self, minValue, maxValue):
        if minValue > maxValue:
            raise ValueError(""minValue must be less than or equal to maxValue"")
        self.minValue = minValue
        self.maxValue = maxValue

    def generate_float(self):
        return random.uniform(self.minValue, self.maxValue)

    def generate_integer(self):
        return round(random.uniform(self.minValue, self.maxValue))

    def __str__(self):
        return f""Random values within range [{self.minValue}, {self.maxValue})""
