def read_and_sort_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Sort the lines alphabetically
        sorted_lines = sorted(lines)

        # Write back to the file
        with open(file_path, 'w') as file:
            file.writelines(sorted_lines)

        # Extract sequence number from the last line and return it
        last_line = sorted_lines[-1]
        parts = last_line.split()
        if len(parts) > 0:
            try:
                seq_number = int(parts[0])  # Assuming the first part is a sequence number
                return seq_number
            except ValueError:
                raise ValueError(""Sequence number is not an integer."")

    except FileNotFoundError:
        print(f""File {file_path} not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
if __name__ == ""__main__"":
    file_path = ""example.txt""
    seq_number = read_and_sort_file(file_path)
    if seq_number is not None:
        print(""Last line sequence number:"", seq_number)
