def read_and_process_file(file_path, start, end):
    import logging

    # Set up logging
    logging.basicConfig(filename='process_log.txt', level=logging.ERROR)

    def custom_sort(lines):
        n = len(lines)
        for i in range(n):
            for j in range(0, n-i-1):
                if int(lines[j].lstrip().split()[0]) > int(lines[j+1].lstrip().split()[0]):
                    lines[j], lines[j+1] = lines[j+1], lines[j]
        return lines

    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        if not (isinstance(start, int) and isinstance(end, int) and start <= end):
            raise ValueError(""Start and end parameters must be integers where start <= end."")

        sorted_lines = custom_sort(lines)
        extracted_sequences = []

        for i in range(len(sorted_lines)):
            line_number = i + 1
            if start <= line_number <= end:
                parts = sorted_lines[i].split()
                sequence_numbers = [int(part) for part in parts[1:] if part.isdigit()]
                extracted_sequences.extend(sequence_numbers)

    except FileNotFoundError:
        logging.error(f""File not found: {file_path}"")
        return []
    except ValueError as ve:
        logging.warning(str(ve))
        return []
    except Exception as e:
        logging.error(f""An unexpected error occurred: {str(e)}"")
        return []

    return extracted_sequences

# Example usage
result = read_and_process_file('example.txt', 2, 5)
print(result)
