from datetime import datetime, timedelta

class EventManager:
    def __init__(self):
        self.events = {}

    def add_event(self, event_id, timestamp, importance_score):
        if event_id in self.events:
            raise ValueError(f""Event with ID {event_id} already exists."")
        self.events[event_id] = {
            ""timestamp"": datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S'),
            ""importance_score"": importance_score
        }

    def update_importance_score(self, event_id, new_score):
        if event_id not in self.events:
            raise ValueError(f""Event with ID {event_id} does not exist."")
        self.events[event_id][""importance_score""] = new_score

    def get_top_n_events(self, n):
        sorted_events = sorted(
            self.events.items(),
            key=lambda item: item[1][""importance_score""],
            reverse=True
        )
        return [(eid, details) for eid, details in sorted_events[:n]]

    def remove_expired_events(self, expiry_duration_days):
        current_time = datetime.now()
        expired_ids = [
            eid for eid, details in self.events.items()
            if (current_time - details[""timestamp""]) > timedelta(days=expiry_duration_days)
        ]
        for eid in expired_ids:
            del self.events[eid]

    def sort_events_by(self, criteria):
        if criteria not in [""timestamp"", ""importance_score""]:
            raise ValueError(""Sort criteria must be 'timestamp' or 'importance_score'."")

        return sorted(
            self.events.items(),
            key=lambda item: item[1][criteria]
        )

# Example usage:
manager = EventManager()
manager.add_event(1, ""2023-11-01 12:00:00"", 50)
manager.add_event(2, ""2023-10-25 14:30:00"", 75)

print(manager.get_top_n_events(2))   # Get top 2 events by score
manager.update_importance_score(1, 90) 

sorted_by_timestamp = manager.sort_events_by(""timestamp"")
for eid, details in sorted_by_timestamp:
    print(f""ID: {eid}, Timestamp: {details['timestamp']}, Score: {details['importance_score']}"")

manager.remove_expired_events(30)  # Remove events older than 30 days
