import json
import uuid
from jsonpath_ng import parse as jsonpath_parse
from typing import List, Dict, Any

class DocumentException(Exception):
    pass

class NoMatchingElementError(DocumentException):
    pass

class MultipleMatchingElementsError(DocumentException):
    pass

class UniqueIDGenerator:
    @staticmethod
    def generate_id():
        return str(uuid.uuid4())

class JSONPathParser:
    @staticmethod
    def parse(json_doc: Dict, path_expression: str) -> List[Dict]:
        jsonpath_expr = jsonpath_parse(path_expression)
        matches = [match.value for match in jsonpath_expr.find(json_doc)]

        if not matches:
            raise NoMatchingElementError(f""No elements found with the expression {path_expression}"")
        elif len(matches) > 1 and isinstance(matches, list):
            raise MultipleMatchingElementsError(f""Multiple elements found with the expression {path_expression}"")

        return matches

class DocumentSearchEngine:
    def __init__(self, documents: List[Dict[str, Any]]):
        self.documents = documents

    def search_by_status(self, document_type: str, status: str) -> List[Dict]:
        return [
            doc for doc in self.documents
            if doc.get('DOCUMENT_TYPE') == document_type and doc.get('STATUS') == status
        ]

class DocumentManagementInterface:
    def __init__(self):
        self.documents = []

    def add_document(self, document_info: Dict[str, Any]):
        self.documents.append(document_info)

    def remove_document(self, document_id: str):
        self.documents = [doc for doc in self.documents if doc.get('DOCUMENT_ID') != document_id]

    def update_document(self, document_id: str, updates: Dict[str, Any]):
        for doc in self.documents:
            if doc.get('DOCUMENT_ID') == document_id:
                doc.update(updates)
                return
        raise DocumentException(f""Document with ID {document_id} not found."")

    def query_documents(self, document_type: str) -> List[Dict]:
        return [doc for doc in self.documents if doc.get('DOCUMENT_TYPE') == document_type]

