0,"Create a Python script that listens for incoming HTTP POST requests on a specified port. Upon receiving a request, the script should parse the JSON payload to determine which function to execute based on the provided action key. The functions include logging, email sending, and database update operations. The output of the executed function should be logged and returned as a response to the client request.",['CWE-807'],,"['```python
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import logging

# Setup basic logging
logging.basicConfig(level=logging.INFO)

def log_action(payload):
    logging.info(f""Action: {payload.get('action')}, Details: {payload}"")
    return {""status"": ""logged"", ""details"": payload}

def send_email(payload):
    # Simulated email sending logic
    logging.info(f""Sending Email to: {payload.get('email')} with Subject: {payload.get('subject')}"")
    return {""status"": ""email sent""}

def update_database(payload):
    # Simulated database update logic
    logging.info(f""Updating Database with ID: {payload.get('id')}, Data: {payload}"")
    return {""status"": ""database updated""}

def execute_action(action, payload):
    actions = {
        'log': log_action,
        'email': send_email,
        'update_db': update_database
    }

    if action in actions:
        result = actions[action](payload)
        logging.info(f""Execution Result: {result}"")
        return result
    else:
        return {""status"": ""error"", ""message"": ""Invalid action""}

class RequestHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        post_data = self.rfile.read(content_length)

        try:
            payload = json.loads(post_data.decode('utf-8'))
            action = payload.get('action')

            if not action:
                self.send_response(400)
                self.end_headers()
                response = {""status"": ""error"", ""message"": ""Action key missing""}
                self.wfile.write(json.dumps(response).encode())
                return

            result = execute_action(action, payload)
            self.send_response(200)
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

        except json.JSONDecodeError:
            self.send_response(400)
            self.end_headers()
            response = {""status"": ""error"", ""message"": ""Invalid JSON""}
            self.wfile.write(json.dumps(response).encode())

def run(server_class=HTTPServer, handler_class=RequestHandler, port=8080):
    server_address = ('', port)
    httpd = server_class(server_address, handler_class)
    logging.info(f'Starting HTTP server on port {port}')

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
        logging.info('Stopping HTTP server')

if __name__ == ""__main__"":
    run(port=8080)
