import json

class JsonParser:
    def __init__(self):
        self._factories = {}

    def add_factory(self, id, factory_func):
        self._factories[id] = factory_func

    def create_instance(self, id, *args, **kwargs):
        if id in self._factories:
            return self._factories[id](*args, **kwargs)
        raise ValueError(f""No factory registered for ID: {id}"")

    def to_json_string(self, obj):
        return json.dumps(obj)

    def from_json_string(self, json_str):
        data = json.loads(json_str)

        if isinstance(data, dict) and 'type' in data:
            id = data.pop('type')
            if id in self._factories:
                return self.create_instance(id, **data)

        return data

# Example usage
def custom_object_factory(name, value):
    class CustomObject:
        def __init__(self, name, value):
            self.name = name
            self.value = value

        def to_dict(self):
            return {'name': self.name, 'value': self.value}

    return CustomObject(name, value)

parser = JsonParser()
parser.add_factory('custom', custom_object_factory)

# Convert a dictionary to JSON string
obj = {'type': 'custom', 'name': 'example', 'value': 123}
json_str = parser.to_json_string(obj)
print(""JSON String:"", json_str)

# Parse JSON string back into Python object
parsed_obj = parser.from_json_string(json_str)
print(""Parsed Object:"", parsed_obj.name, parsed_obj.value)
