def grammar_lexer(input_file_path):
    tokens = ('IDENTIFIER', 'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE',
              'LPAREN', 'RPAREN')

    t_PLUS = r'\+'
    t_MINUS = r'-'
    t_TIMES = r'\*'
    t_DIVIDE = r'/'
    t_LPAREN = r'\('
    t_RPAREN = r'\)'

    def t_IDENTIFIER(t):
        r'[a-zA-Z_][a-zA-Z0-9_]*'
        return Token('IDENTIFIER', t.value)

    def t_NUMBER(t):
        r'\d+'
        return Token('NUMBER', t.value)

    t_ignore = ' \t\n'

    def t_error(t):
        print(f""Illegal character '{t.value[0]}'"")
        t.lexer.skip(1)

    lexer = lex.lex()
    with open(input_file_path, 'r') as file:
        data = file.read()
    lexer.input(data)

    tokens_list = []
    for tok in iter(lexer.token, None):
        tokens_list.append(tok)
    return tokens_list

def grammar_parser(grammar_obj):
    def p_expression_binop(p):
        '''expression : expression PLUS term
                      | expression MINUS term'''
        p[0] = (p[1], p[2], p[3])

    def p_expression_term(p):
        'expression : term'
        p[0] = p[1]

    def p_term_factor(p):
        '''term : term TIMES factor
                | term DIVIDE factor'''
        p[0] = (p[1], p[2], p[3])

    def p_term_factor_only(p):
        'term : factor'
        p[0] = p[1]

    def p_factor_group(p):
        'factor : LPAREN expression RPAREN'
        p[0] = p[2]

    def p_factor_number(p):
