from neo4j import GraphDatabase, basic_auth
import requests

class EnhancedRandomGenerator:
    @staticmethod
    def random_number(min_value, max_value):
        return random.randint(min_value, max_value)

def get_oauth_token(client_id, client_secret):
    response = requests.post('https://auth-service.com/oauth/token', data={
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    })
    if response.status_code == 200:
        return response.json().get('access_token')
    else:
        raise Exception(""Failed to retrieve OAuth token"")

def create_graph_with_random_properties(uri, oauth_client_id, oauth_client_secret, num_vertices=5):
    try:
        if not isinstance(num_vertices, int) or num_vertices <= 0:
            raise ValueError(""num_vertices must be a positive integer"")

        token = get_oauth_token(oauth_client_id, oauth_client_secret)
        driver = GraphDatabase.driver(uri, auth=basic_auth(token, ''))

        with driver.session() as session:
            for _ in range(num_vertices):
                vertex_label = f""Label_{EnhancedRandomGenerator.random_number(1, 10)}""
                vertex_properties = {
                    ""prop1"": EnhancedRandomGenerator.random_number(1, 100),
                    ""prop2"": EnhancedRandomGenerator.random_number(1, 50)
                }

                query = (
                    f""MATCH (a) ""
                    f""WITH a, {vertex_label} AS label ""
                    f""CREATE (b:{label} {{ prop1: $prop1, prop2: $prop2 }}), ""
                    f""(a)-[r:CONNECTED]->(b)""
                )
                session.run(query, **vertex_properties)

    except ValueError as ve:
        print(f""Input Error: {ve}"")
    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
create_graph_with_random_properties(""bolt://localhost:7687"", ""your_client_id"", ""your_client_secret"")
```

