0,"Create a program that reads text files line by line, dynamically allocating memory for each line's content. For each line, calculate the average of the last two numeric fields and concatenate this average with the original line in a comma-separated format. Incorporate error handling for issues like insufficient memory, file not found, or non-numeric input. Support processing multiple files using command-line arguments and provide an option to output results either to a new file or display them on the console based on user choice during program execution. Enhance usability with comments and proper code structure, including separate functions for different tasks such as readFile, calculateAverage, and outputResults. Optimize memory usage by reusing allocations when possible and implement unit tests to ensure all functions work correctly under various conditions, covering edge cases. The goal is to expand upon the initial task by adding complexity through these additional features and practices.",['CWE-120'],,"['```python
import sys
import os

def read_file(file_path):
    """"""Reads a file line by line and returns its lines.""""""
    try:
        with open(file_path, 'r') as file:
            return file.readlines()
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found."")
        return []
    except Exception as e:
        print(f""An error occurred while reading the file: {e}"")
        return []

def calculate_average(line):
    """"""Calculates the average of the last two numeric fields in a line.""""""
    try:
        parts = line.strip().split()
        # Get the last two numeric fields
        numbers = [float(parts[-2]), float(parts[-1])]
        avg = sum(numbers) / len(numbers)
        return f""{line.strip()},{avg:.2f}""
    except (ValueError, IndexError):
        print(f""Warning: Non-numeric or insufficient data in line: {line.strip()}"")
        return None

def output_results(results, output_option, output_file=None):
    """"""Outputs results to a file or console based on user choice.""""""
    if output_option == ""file"":
        try:
            with open(output_file, 'w') as file:
                for result in results:
                    file.write(result + ""\n"")
            print(f""Results successfully written to '{output_file}'."")
        except Exception as e:
            print(f""An error occurred while writing to the file: {e}"")
    elif output_option == ""console"":
        for result in results:
            print(result)

def process_files(file_paths, output_option):
    """"""Processes multiple files and handles output.""""""
    results = []
    for file_path in file_paths:
        lines = read_file(file_path)
        for line in lines:
            processed_line = calculate_average(line)
            if processed_line:
                results.append(processed_line)

    if not output_option or output_option == ""console"":
        output_results(results, ""console"")
    elif output_option == ""file"":
        output_filename = input(""Enter the name of the output file: "")
        output_results(results, ""file"", output_filename)

def main():
    """"""Main function to execute the program.""""""
    if len(sys.argv) < 3:
        print(""Usage: python script.py [files...] --output [console|file]"")
        return

    # Extract files and output option from command-line arguments
    file_paths = []
    output_option = None
    for arg in sys.argv[1:]:
        if arg.startswith(""--output=""):
            output_option = arg.split(""="")[1]
        elif not arg.startswith(""--""):
            file_paths.append(arg)

    process_files(file_paths, output_option)

if __name__ == ""__main__"":
    main()
```

