        self.name = name
        self.domain = domain
        self.range = range_
        self.intercepts = intercepts if intercepts else []
        self.critical_points = critical_points if critical_points else []

    def evaluate(self, x):
        # Example: Simple quadratic function evaluation
        if self.name == ""quadratic"":
            return 3 * x**2 + 2 * x - 5
        elif self.name == ""sinusoidal"":
            return math.sin(x)
        # Add more function evaluations as needed
        raise ValueError(""Function not implemented"")

    def validate_key_points(self):
        for point in self.intercepts:
            if point not in self.domain:
                raise ValueError(f""Intercept {point} is out of domain"")

        for cp in self.critical_points:
            if cp[0] not in self.domain or cp[1] < self.range[0] or cp[1] > self.range[1]:
                raise ValueError(f""Critical point {cp} is invalid"")

class FunctionGenerator:
    def __init__(self, xml_path):
        self.xml_root = ET.parse(xml_path).getroot()

    def parse_xpath(self, path):
        elements = self.xml_root.findall(path)
        if not elements:
            raise LookupError(""Element not found"")
        if len(elements) > 1:
            raise LookupError(""Multiple elements found"")
        return elements[0]

    def generate_functions(self, count):
        functions = []
        for _ in range(count):
            try:
                func_data = self.create_random_function()
                functions.append(func_data)
            except MemoryError:
                print(""Memory allocation failed"")
                break
        return functions

    def create_random_function(self):
        # Randomly create a mathematical function
        function_name = random.choice([""quadratic"", ""sinusoidal""])

        domain = (random.uniform(-10, 10), random.uniform(0, 20))
        range_ = (-100, 100)

        intercepts = [domain[0]]
        critical_points = [(random.uniform(*domain), random.uniform(*range_))]

        func_data = FunctionData(function_name, domain, range_, intercepts, critical_points)
        func_data.validate_key_points()
        return func_data

# Example Usage
try:
    generator = FunctionGenerator(""math_functions.xml"")
    functions = generator.generate_functions(5)

    for f in functions:
        print(f""Function: {f.name}, Domain: {f.domain}, Range: {f.range}"")
        result = f.evaluate(random.uniform(*f.domain))
        print(f""Evaluation at a point: {result}"")

except LookupError as le:
    print(le)
except ValueError as ve:
    print(ve)
