from typing import List

def filter_by_threshold(int_list: List[int], threshold: int, operation_flag: str = 'exclude') -> List[int]:
    # Check if the input types are valid
    if not isinstance(int_list, list) or not all(isinstance(i, int) for i in int_list):
        raise ValueError(""int_list must be a list of integers."")
    if not isinstance(threshold, int):
        raise ValueError(""threshold must be an integer."")
    if operation_flag not in ['exclude', 'include']:
        raise ValueError(""operation_flag must be either 'exclude' or 'include'."")

    # Return empty list if threshold is negative
    if threshold < 0:
        return []

    # Filter the list based on the operation flag
    if operation_flag == 'exclude':
        return [x for x in int_list if x < threshold]
    elif operation_flag == 'include':
        return [x for x in int_list if x >= threshold]

# Example usage and test cases:
print(filter_by_threshold([1, 2, 3, 4, 5], 3))            # Default 'exclude': [1, 2]
print(filter_by_threshold([1, 2, 3, 4, 5], 3, 'include')) # 'include': [3, 4, 5]
print(filter_by_threshold([1, 2, 3, 4, 5], -1))           # Negative threshold: []
try:
    print(filter_by_threshold(""not a list"", 3))
except ValueError as e:
    print(e)
try:
    print(filter_by_threshold([1, 'two', 3], 3))
except ValueError as e:
    print(e)
try:
    print(filter_by_threshold([1, 2, 3], 3, 'invalid'))
except ValueError as e:
    print(e)
