import re
from collections import defaultdict

class SQLQueryAnalyzer:
    def __init__(self):
        self.tables = {}
        self.columns = defaultdict(list)
        self.query_cache = {}

    def parse_query(self, sql_query, sort_by='table', cache_enabled=True):
        if cache_enabled and sql_query in self.query_cache:
            return self.query_cache[sql_query]

        parsed_data = {}
        current_table = None

        query_parts = sql_query.strip().split("" "")

        for part in query_parts:
            if part.upper() == ""FROM"":
                current_table = True
            elif part.upper() == ""JOIN"":
                current_table = True
            elif part.upper() == ""WHERE"":
                break
            elif current_table:
                match = re.match(r'(\w+)\.(\w+)', part)
                if match:
                    table_name, column_name = match.groups()
                    self.tables.setdefault(table_name, []).append(column_name)
                    self.columns[table_name].append(column_name)

        parsed_data['tables'] = sorted(self.tables.items(), key=lambda x: x[0] if sort_by == 'table' else x[1])
        parsed_data['columns'] = sorted(self.columns.items(), key=lambda x: x[0] if sort_by == 'column' else list(set(x[1])))

        if cache_enabled:
            self.query_cache[sql_query] = parsed_data

        return parsed_data

    def analyze_complexity(self, sql_query):
        complexity_score = 0
        complexity_keywords = [""JOIN"", ""WHERE"", ""GROUP BY"", ""ORDER BY"", ""LIMIT""]

        for keyword in complexity_keywords:
            if keyword in sql_query:
                complexity_score += 1

        subquery_count, nested_join_count, join_count, select_star_count, order_by_count, limit_count, distinct_count = 0, 0, 0, False, False, False, False

        depth_counter_stack = []

        for token in re.split(r'(?<=[.,])', sql_query):
            token_lowered_strip_quotes = token.lower().strip(""'\"""")

            if token_lowered_strip_quotes.startswith('select'):
                select_star_count |= token_lowered_strip_quotes.endswith('*')

            elif token_lowered_strip_quotes.startswith('order by'):
                order_by_count = True

            if 'select' in token_lowered_strip_quotes and ')' in token:
                subquery_count += 1
                depth_counter_stack.append(token.count('(') - token.count(')'))

            if 'join' in token_lowered_strip_quotes:
                join_count += 1
                if any(d > 0 for d in depth_counter_stack):
                    nested_join_count += 1

        return {
            ""complexity_score"": complexity_score,
            ""subquery_count"": subquery_count,
            ""nested_join_count"": nested_join_count,
            ""join_count"": join_count,
            ""select_star_count"": select_star_count,
            ""order_by_count"": order_by_count
        }
