def slugify(input_string, append_timestamp=False):
    if not is_valid_input(input_string):
        raise ValueError(""Input contains forbidden characters."")

    # Replace spaces and special characters with hyphens
    slug = re.sub(r'[^a-zA-Z]', '-', input_string)
    slug = re.sub(r'-+', '-', slug).strip('-').lower()

    if append_timestamp:
        timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
        slug += f""-{timestamp}""

    return slug

# Unit tests
import unittest

class TestSlugify(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(slugify('', False), '')

    def test_invalid_characters(self):
        with self.assertRaises(ValueError):
            slugify('Hello@World!')

    def test_special_chars_and_numbers(self):
        self.assertEqual(slugify('Hello World 123!'), 'hello-world')

    def test_with_timestamp(self):
        result = slugify('Example String', True)
        timestamp_part = re.search(r'\d{14}$', result).group(0)
        self.assertTrue(result.endswith(f'-{timestamp_part}'))

if __name__ == '__main__':
    unittest.main()

# Script for processing CSV files
import csv

def process_csv(input_file, output_file):
    with open(input_file, mode='r') as infile, open(output_file, mode='w', newline='') as outfile:
        reader = csv.reader(infile)
        writer = csv.writer(outfile)

        for row in reader:
            if not row:
                continue
            url_slug = slugify(row[0], append_timestamp=True)
            writer.writerow([row[0], url_slug])

if __name__ == '__main__':
    input_csv_path = 'input_urls.csv'
    output_csv_path = 'output_slugs.csv'
    process_csv(input_csv_path, output_csv_path)
