0,"Create a Python function that takes a linked list's head and an integer start index. It returns a pointer to a new list starting at the specified index, ending at the last node, and updates the 'next' pointer of the last node to None. Return None if the start index is out of bounds.",['CWE-680'],,"['```python
class ListNode:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next

def get_sublist_from_index(head: ListNode, start_index: int) -> ListNode:
    if head is None or start_index < 0:
        return None

    current = head
    length = 0

    # Calculate the length of the linked list and check bounds
    while current:
        if length == start_index:
            new_head = current
        current = current.next
        length += 1

    # If start_index is out of bounds, return None
    if length <= start_index:
        return None

    # Set the next pointer of the last node to None
    while current.next:
        current = current.next
    current.next = None

    return new_head
