import time
from collections import defaultdict

# Mock classes for demonstration purposes.
class Packet:
    def __init__(self, protocol, source_ip, dest_ip, size):
        self.protocol = protocol
        self.source_ip = source_ip
        self.dest_ip = dest_ip
        self.size = size

class NetworkMonitor:
    def __init__(self, qos_policies, security_thresholds):
        self.qos_policies = qos_policies
        self.security_thresholds = security_thresholds
        self.traffic_log = defaultdict(list)

    def monitor_packet(self, packet: Packet):
        # Categorize packet
        category = (packet.protocol, packet.source_ip, packet.dest_ip)

        # Log traffic by category
        self.traffic_log[category].append(packet.size)

        # Apply QoS policies
        self.apply_qos_policies(category, packet)

        # Check for unusual network activity
        self.check_security_thresholds(category)

    def apply_qos_policies(self, category, packet: Packet):
        protocol = category[0]
        if protocol in self.qos_policies:
            policy = self.qos_policies[protocol]

            if 'prioritize' in policy and protocol == policy['prioritize']:
                print(f""Prioritizing {category}"")

            elif 'bandwidth_limit' in policy:
                bandwidth_used = sum(self.traffic_log[category])
                if bandwidth_used > policy['bandwidth_limit']:
                    print(f""Limiting bandwidth for {category}"")

    def check_security_thresholds(self, category):
        size_total = sum(self.traffic_log[category])
        threshold = self.security_thresholds.get(category, None)

        if threshold and size_total > threshold:
            print(f""Alert: Unusual activity detected for {category}. Total size: {size_total}"")

def main():
    # Define QoS policies
    qos_policies = {
        'VoIP': {'prioritize': True},
        'video_streaming': {'bandwidth_limit': 10000},  # Example limit in bytes
    }

    # Define security thresholds
    security_thresholds = {
        ('TCP', '192.168.1.1', '10.0.0.1'): 5000,
    }

    network_monitor = NetworkMonitor(qos_policies, security_thresholds)

    packets = [
        Packet('VoIP', '192.168.1.2', '10.0.0.2', 300),
        Packet('video_streaming', '192.168.1.3', '10.0.0.3', 5000),
        # Add more test packets
    ]

    for packet in packets:
        network_monitor.monitor_packet(packet)
        time.sleep(1)  # Simulating real-time monitoring

if __name__ == ""__main__"":
    main()
