import json
import xml.etree.ElementTree as ET
from typing import Dict, Any, Optional

def apply_rules(data: Any, rules: Dict[str, Any], parent_key: str = '') -> Any:
    # Base case for recursion
    if isinstance(data, dict):
        return {key: apply_rules(value, rules, key) for key, value in data.items()}
    elif isinstance(data, list):
        return [apply_rules(item, rules, parent_key) for item in data]
    else:
        rule = rules.get(parent_key)
        if callable(rule):
            return rule(data)
        return data

def json_to_xml(json_obj: Any, line_padding: str = '', rules: Dict[str, Any] = {}, namespaces: Optional[Dict[str, str]] = None) -> ET.Element:
    if isinstance(json_obj, dict):
        element = list(json_obj.keys())[0]
        sub_element = apply_rules(json_obj[element], rules)

        # Add namespace
        ns_tag = ''
        if namespaces and element in namespaces:
            ns_tag = f' xmlns=""{namespaces[element]}""'

        xml_element = ET.Element(f'{element}{ns_tag}')
        for key, value in sub_element.items():
            child = json_to_xml({key: value}, line_padding + '  ', rules, namespaces)
            xml_element.append(child)
    elif isinstance(json_obj, list):
        xml_elements = []
        for item in json_obj:
            element = json_to_xml(item, line_padding, rules, namespaces)
            xml_elements.append(element)
        return ET.Element('items') if xml_elements else ET.Element('item')
    else:
        xml_element = ET.Element('value')
        xml_element.text = str(json_obj)
        return xml_element
    return xml_element

def convert_json_to_xml(input_file: str, output_file: str, rules: Dict[str, Any], preserve_comments: bool = False, namespaces: Optional[Dict[str, str]] = None):
    try:
        with open(input_file, 'r') as file:
            content = file.read()

        # Remove comments if not preserving
        if not preserve_comments:
            import re
            json_data = re.sub(r'(?<!\\)//.*', '', content)
            json_obj = json.loads(json_data)
        else:
            # Parse JSON with comments using a custom approach or library like `commentjson`
            import commentjson as cj
            json_obj = cj.load(content)

    except (json.JSONDecodeError, Exception) as e:
        print(f""Failed to read JSON: {e}"")
        return

    try:
        root_element = json_to_xml(json_obj, rules=rules, namespaces=namespaces)

        # Convert element tree to string
        xml_str = ET.tostring(root_element, encoding='unicode', method='xml')

        if preserve_comments:
            # Insert comments back into the XML string (requires additional handling logic)
            pass

        with open(output_file, 'w') as file:
            file.write(xml_str)

    except Exception as e:
        print(f""Failed to write XML: {e}"")

