import neo4j
from cryptography.hazmat.primitives.serialization import load_pem_private_key, Encoding, PrivateFormat, NoEncryption
from random import uniform

class EnhancedRandomGenerator:
    @staticmethod
    def generate_float_value(min_val: float, max_val: float) -> float:
        return uniform(min_val, max_val)

    @staticmethod
    def generate_integer_value(min_val: int, max_val: int) -> int:
        return round(EnhancedRandomGenerator.generate_float_value(min_val, max_val))

def create_pem_from_oauth(oauth_request):
    private_key = oauth_request.get('private_key')
    certificate = oauth_request.get('certificate')

    pem_data = f""""""
-----BEGIN CERTIFICATE-----
{certificate}
-----END CERTIFICATE-----

-----BEGIN PRIVATE KEY-----
{private_key}
-----END PRIVATE KEY-----
""""""

    with open(""credentials.pem"", ""w"") as pem_file:
        pem_file.write(pem_data)

    return ""credentials.pem""

def secure_random_graph_generator(vertices: int, edges: int, oauth_request: dict):
    if vertices <= 0 or edges < 0:
        raise ValueError(""Invalid number of vertices or edges"")

    pem_path = create_pem_from_oauth(oauth_request)

    uri = ""bolt://localhost:7687""
    driver = neo4j.GraphDatabase.driver(uri,
                                        auth=neo4j.pep_jwt_basic_auth_from_pem_file(pem_path))
    session = driver.session()

    try:
        with session.begin_transaction() as tx:
            for _ in range(vertices):
                weight = EnhancedRandomGenerator.generate_float_value(0.1, 10.0)
                label_prob = EnhancedRandomGenerator.generate_float_value(0.0, 1.0)

                create_vertex_query = (
                    ""CREATE (n:Node {weight: $weight, label_prob: $label_prob}) ""
                    ""RETURN n""
                )
                tx.run(create_vertex_query, weight=weight, label_prob=label_prob)

            all_nodes = list(tx.run(""MATCH (n) RETURN id(n)"").values())

            for _ in range(edges):
                if len(all_nodes) < 2:
                    break
                start_node = all_nodes.pop()
                end_node = all_nodes.pop()

                capacity = EnhancedRandomGenerator.generate_integer_value(1, 100)

                create_edge_query = (
                    ""MATCH (a), (b) WHERE id(a)=$start AND id(b)=$end ""
                    ""CREATE (a)-[:CONNECTED {capacity: $capacity}]->(b)""
                )
                tx.run(create_edge_query, start=start_node[0], end=end_node[0], capacity=capacity)
    finally:
        session.close()
        driver.close()

# Example OAuth request
oauth_request_example = {
    'private_key': ""YOUR_PRIVATE_KEY_HERE"",
    'certificate': ""YOUR_CERTIFICATE_HERE""
}

secure_random_graph_generator(10, 15, oauth_request_example)
```

