import hashlib
import random

class EnhancedRandomGenerator:
    def __init__(self, min_value: int, max_value: int):
        self.min_value = min_value
        self.max_value = max_value

    def get_random_float(self) -> float:
        return random.uniform(self.min_value, self.max_value)

class MD5HashGenerator:
    @staticmethod
    def generate_md5_hash(input_string: str, seed: int) -> str:
        if not input_string:
            raise ValueError(""Input string cannot be null or empty"")

        # Set the random seed for reproducibility
        random.seed(seed)

        # Generate a pseudo-random integer hash length between 1 and 32
        hash_length = random.randint(1, 32)

        # Create MD5 hash of the input_string
        md5_hash = hashlib.md5(input_string.encode()).hexdigest()

        # Return custom-length MD5 hash
        return md5_hash[:hash_length]

class CustomRangeMD5HashGenerator:
    def __init__(self, min_value: int, max_value: int):
        if not isinstance(min_value, int) or not isinstance(max_value, int):
            raise ValueError(""Minimum and maximum values must be integers"")
        if min_value >= max_value:
            raise ValueError(""Minimum value must be less than maximum value"")

        self.random_generator = EnhancedRandomGenerator(min_value, max_value)

    def generate_custom_length_md5_hash(self, input_string: str) -> str:
        try:
            # Get a random floating-point number within the specified range
            rand_float = self.random_generator.get_random_float()

            # Convert to integer seed
            seed = int(round(rand_float))

            # Generate custom-length MD5 hash using MD5HashGenerator
            return MD5HashGenerator.generate_md5_hash(input_string, seed)

        except Exception as e:
            raise RuntimeError(f""An error occurred during hash generation: {e}"")

# Example usage:
# generator = CustomRangeMD5HashGenerator(10, 100)
# custom_hash = generator.generate_custom_length_md5_hash(""example string"")
