import hashlib
import os
from typing import List, Tuple

def calculate_md5_hash(file_path: str) -> str:
    chunk_size = 65536  # Chunk size for reading the file
    hash_object = hashlib.md5()

    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hash_object.update(chunk)

    return hash_object.hexdigest()

def verify_file_integrity(file_path: str, expected_hash: str) -> bool:
    calculated_hash = calculate_md5_hash(file_path)
    return calculated_hash == expected_hash

def check_file_integrity_multiple_files(directory_path: str, expected_hashes: List[Tuple[str, str]]) -> bool:
    for relative_path, expected_hash in expected_hashes:
        full_path = os.path.join(directory_path, relative_path)
        if not verify_file_integrity(full_path, expected_hash):
            return False
    return True
