import hashlib
import os

def calculate_md5_hash(file_path):
    """"""Calculate the MD5 hash of a file.""""""
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def verify_file_integrity(file_path, expected_hash):
    """"""Verify if the file's MD5 hash matches the expected hash.""""""
    calculated_hash = calculate_md5_hash(file_path)
    return calculated_hash == expected_hash

def check_file_integrity_multiple_files(directory_path, expected_hashes):
    """"""Check integrity of multiple files in a directory against their expected hashes.""""""
    for file_path, expected_hash in expected_hashes:
        full_file_path = os.path.join(directory_path, file_path)
        if not verify_file_integrity(full_file_path, expected_hash):
            return False
    return True
