import hashlib
import os

def calculate_and_rename(file_path, num_digits, hash_type=""md5"", new_extension=None):
    # Check if file exists
    if not os.path.isfile(file_path):
        return ""File not found""

    # Calculate hash based on type
    if hash_type == ""md5"":
        hasher = hashlib.md5()
    elif hash_type == ""sha1"":
        hasher = hashlib.sha1()
    elif hash_type == ""sha224"":
        hasher = hashlib.sha224()
    elif hash_type == ""sha256"":
        hasher = hashlib.sha256()
    elif hash_type == ""sha384"":
        hasher = hashlib.sha384()
    elif hash_type == ""sha512"":
        hasher = hashlib.sha512()

    with open(file_path, 'rb') as f:
        while chunk := f.read(1024 * 1024):
            hasher.update(chunk)

    # Extract original file extension
    _, original_extension = os.path.splitext(file_path)

    # Construct new filename with updated extension
    if new_extension is None:
        new_extension = f""{original_extension[:-1]}{str(num_digits).zfill(len(original_extension) - 1)}""
    else:
        new_extension = str(new_extension)

    # Return new filename in hexadecimal format
    return f""{hasher.hexdigest()} {new_extension}""

# Example usage:
# result_md5_with_new_ext = calculate_and_rename(""/path/to/your/file.txt"", 3, ""md5"", "".newext"")
# result_sha1_with_existing_ext = calculate_and_rename(""/path/to/your/file.txt"", 3, ""sha1"")
