class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def sublist_from_index(head: ListNode, start_index: int) -> ListNode:
    if not head or start_index < 0:
        return None

    current = head
    index = 0

    while current and index < start_index - 1:
        current = current.next
        index += 1

    if not current:
        return None

    new_head = current
    while current.next:
        current = current.next

    current.next = None
    return new_head
