import json
import xml.etree.ElementTree as ET
from collections import defaultdict

def process_json_to_xml(json_file_path, xml_output_path, namespace=None, preserve_comments=False):
    try:
        with open(json_file_path, 'r') as file:
            json_data = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f""Invalid JSON file or path: {e}"")

    root = ET.Element('root')
    transform_json_to_xml(json_data, root, namespace=namespace)

    if preserve_comments:
        preserve_comments_in_xml(root)

    tree = ET.ElementTree(root)
    tree.write(xml_output_path)

def transform_json_to_xml(data, parent_element, namespace=None):
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, (dict, list)):
                child_element = ET.SubElement(parent_element, key)
                transform_json_to_xml(value, child_element)
            else:
                tag = key.replace('_', ' ').title()
                if namespace:
                    tag = f""{namespace}{' '.join(tag.split())}""
                element = ET.SubElement(parent_element, tag)
                element.text = str(value)
    elif isinstance(data, list):
        for item in data:
            transform_json_to_xml(item, parent_element)

def preserve_comments_in_xml(element):
    if element.text is not None and '<' not in element.text and '>' not in element.text:
        comment_text = ''.join([c.tail for c in element.getchildren()])
        if comment_text.strip():
            comment_node = ET.Comment(comment_text.strip())
            comment_node.tail = '\n'
            element.insert(0, comment_node)

