KEY = b'Sixteen byte key'  # Example key (must be 16 bytes for AES-128)
IV = get_random_bytes(16)  # Initialization vector


def AES_encrypt(data):
    try:
        cipher = AES.new(KEY, AES.MODE_CFB, IV)
        return cipher.encrypt(data.encode())
    except Exception as e:
        return None


class AccountManager:
    def __init__(self):
        self.accounts = {}
        self.transactions_queue = queue.Queue()
        self.semaphore = threading.Semaphore(10)
        self.error_log = logging.getLogger('error')
        self.info_log = logging.getLogger('info')

    def add_account(self, account_id, initial_balance):
        if account_id in self.accounts:
            return False
        self.accounts[account_id] = {'balance': initial_balance}
        return True

    def add_transaction(self, transaction):
        if not transaction['amount']:
            return False

        from_id, to_id = transaction['from'], transaction['to']

        if from_id not in self.accounts or to_id not in self.accounts:
            return False

        with threading.Lock():
            from_balance = self.accounts[from_id]['balance']

            if from_balance < transaction['amount']:
                return False

            # Update balances
            self.accounts[from_id]['balance'] -= transaction['amount']
            self.accounts[to_id]['balance'] += transaction['amount']

            encrypted_email = AES_encrypt(transaction.get('email', ''))

            if not encrypted_email:
                self.error_log.error(f""Failed to encrypt email: {transaction.get('email')}"")
                return False

            encrypted_transaction = {
                'account_from': from_id,
                'account_to': to_id,
                'amount': transaction['amount'],
                'encrypted_email': encrypted_email,
                'timestamp': datetime.now(),
                'age_days': (datetime.now() - timedelta(days=7)).timestamp(),
                'valid_transaction': True,
            }

            self.transactions_queue.put(encrypted_transaction)

        return True

    def update_account_balances(self, account_id, balance):
        if account_id in self.accounts:
            with threading.Lock():
                self.accounts[account_id]['balance'] = balance
