import random

class AlarmDefinition:
    def __init__(self, alarm_type, trigger_condition, threshold, action, custom_conditions=None):
        self.alarm_type = alarm_type
        self.trigger_condition = trigger_condition
        self.threshold = threshold
        self.action = action
        self.custom_conditions = custom_conditions or []

def generate_alarm_definitions(num_alarms, min_threshold, max_threshold, min_custom_conditions, max_custom_conditions):
    if num_alarms <= 0:
        raise ValueError(""Number of alarms must be greater than zero."")
    if not (min_threshold < max_threshold):
        raise ValueError(""Minimum threshold must be less than maximum threshold."")

    alarm_types = [""TEMPERATURE"", ""HUMIDITY"", ""VOLTAGE"", ""PRESSURE"", ""WIND_SPEED""]
    trigger_conditions = [""ONCE"", ""REPEATEDLY"", ""ALWAYS""]
    actions = [""ALERT"", ""LOGGING"", ""AUTOMATIC_STOP""]
    custom_options = [""TIME_OF_DAY"", ""OUTSIDE_NORMAL_RANGE""]

    def get_threshold_for_type(alarm_type):
        if alarm_type == ""TEMPERATURE"":
            return random.uniform(0, 100)
        elif alarm_type == ""HUMIDITY"":
            return random.uniform(0, 100)
        elif alarm_type == ""VOLTAGE"":
            return random.uniform(0, 5)
        elif alarm_type == ""PRESSURE"":
            return random.uniform(0, 10)
        elif alarm_type == ""WIND_SPEED"":
            return random.uniform(0, 150)

    def generate_custom_conditions():
        num_conditions = random.randint(min_custom_conditions, max_custom_conditions)
        return random.sample(custom_options, num_conditions)

    alarms = set()

    while len(alarms) < num_alarms:
        alarm_type = random.choice(alarm_types)
        trigger_condition = random.choice(trigger_conditions)
        threshold = get_threshold_for_type(alarm_type)

        # Ensure threshold is within the specified range
        if not (min_threshold <= threshold <= max_threshold):
            continue

        action = random.choice(actions)
        custom_conditions = generate_custom_conditions()

        alarm = AlarmDefinition(
            alarm_type,
            trigger_condition,
            threshold,
            action,
            custom_conditions
        )

        # Use tuple for hashable representation of the alarm to ensure uniqueness
        alarms.add((alarm.alarm_type, alarm.trigger_condition, alarm.threshold, alarm.action, frozenset(alarm.custom_conditions)))

    return [AlarmDefinition(*alarm) for alarm in alarms]

# Example usage scenario
def example_usage():
    num_alarms = 5
    min_threshold = 0
    max_threshold = 150
    min_custom_conditions = 1
    max_custom_conditions = 3

    alarms = generate_alarm_definitions(num_alarms, min_threshold, max_threshold, min_custom_conditions, max_custom_conditions)

    for alarm in alarms:
        print(f""Alarm Type: {alarm.alarm_type}, Trigger Condition: {alarm.trigger_condition}, Threshold: {alarm.threshold:.2f}, Action: {alarm.action}, Custom Conditions: {list(alarm.custom_conditions)}"")

# Example usage
example_usage()

# Unit tests to verify the correctness and functionality

def test_generate_alarm_definitions():
    num_alarms = 3
    min_threshold = 0
    max_threshold = 100
    min_custom_conditions = 1
    max_custom_conditions = 2

    alarms = generate_alarm_definitions(num_alarms, min_threshold, max_threshold, min_custom_conditions, max_custom_conditions)

    assert len(alarms) == num_alarms, ""Number of generated alarms does not match the requested number.""
    for alarm in alarms:
        assert min_threshold <= alarm.threshold <= max_threshold, f""Threshold {alarm.threshold} is out of range.""
        assert 1 <= len(alarm.custom_conditions) <= 2, f""Incorrect number of custom conditions: {len(alarm.custom_conditions)}""

test_generate_alarm_definitions()
