import re
from collections import defaultdict

class SQLQueryAnalyzer:
    def __init__(self):
        self.tables = {}
        self.columns = defaultdict(list)
        self.query_cache = {}

    def parse_query(self, sql_query, sort_by='table', cache_enabled=True):
        if cache_enabled and sql_query in self.query_cache:
            return self.query_cache[sql_query]

        parsed_data = {}
        current_table = None

        query_parts = sql_query.strip().split("" "")

        for part in query_parts:
            if part.upper() == ""FROM"":
                current_table = True
            elif part.upper() == ""JOIN"":
                current_table = True
            elif part.upper() == ""WHERE"":
                break
            elif current_table:
                match = re.match(r'(\w+)\.(\w+)', part)
                if match:
                    table_name, column_name = match.groups()
                    self.tables.setdefault(table_name, []).append(column_name)
                    self.columns[table_name].append(column_name)

        parsed_data['tables'] = sorted(self.tables.items(), key=lambda x: x[0]) if sort_by == 'table' else sorted(self.tables.items(), key=lambda x: x[1])
        parsed_data['columns'] = sorted(self.columns.items(), key=lambda x: x[0]) if sort_by == 'column' else sorted(self.columns.items(), key=lambda x: list(set(x[1])))

        if cache_enabled:
            self.query_cache[sql_query] = parsed_data

        return parsed_data

    def analyze_complexity(self, sql_query):
        complexity_score = 0

        # Check for specific keywords with different weights
        complexity_keywords_weighted = {""JOIN"": 2, ""WHERE"": 1.5, ""GROUP BY"": 1.25,
                                        ""ORDER BY"": 1.75, ""LIMIT"": 2.5}

        for keyword in complexity_keywords_weighted:
            if keyword.upper() in sql_query.upper():
                complexity_score += complexity_keywords_weighted[keyword]

        return complexity_score

    def calculate_select_star(self, sql_query):
        query_upper = sql_query.upper()
        return ""SELECT *"" in query_upper or (""SELECT"" in query_upper and not any(column in query_upper for column in self.columns))

# Example usage
analyzer = SQLQueryAnalyzer()
parsed_data = analyzer.parse_query(""SELECT a.name FROM users a JOIN orders b ON a.id = b.user_id WHERE b.amount > 100"")
complexity_score = analyzer.analyze_complexity(parsed_data)
select_star_check = analyzer.calculate_select_star(""SELECT * FROM users"")
