import json
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes

def pad_data(data, block_size=16):
    padding_length = block_size - (len(data) % block_size)
    padding_value = chr(padding_length) * padding_length
    return data + padding_value.encode()

def remove_padding(data):
    padding_length = ord(data[-1])
    return data[:-padding_length]

class SecureJSONParser:
    def __init__(self):
        self.key = get_random_bytes(32)
        self.iv = get_random_bytes(16)
        self.registry = {}

    def encrypt_json(self, data):
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        data_json = json.dumps(data).encode()
        padded_data = pad_data(data_json)
        return cipher.encrypt(padded_data)

    def decrypt_json(self, encrypted_data):
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        decrypted_padded_data = cipher.decrypt(encrypted_data)
        decrypted_data = remove_padding(decrypted_padded_data)
        return json.loads(decrypted_data.decode())

    def validate_crc_flag(self, obj):
        # Example: Using a simple checksum for validation
        return 'CRCFLAG' in obj

    def add_factory_function(self, id_, factory_function):
        self.registry[id_] = factory_function

    def create_instance(self, id_, *args):
        if id_ not in self.registry:
            raise ValueError(f""No factory registered under ID: {id_}"")
        return self.registry[id_](self, *args)

# Factory functions registry example
class CustomJSONFactory:
    def __init__(self, parser: SecureJSONParser):
        # Example custom initialization
        pass

def register_custom_factory(parser: SecureJSONParser):
    parser.add_factory_function(""custom"", CustomJSONFactory)

def create_custom_instance(parser: SecureJSONParser):
    return parser.create_instance(""custom"")

# Example usage:
