                balance = balance or None

                if not self.validate_account_record(username, email, None, None, balance):
                    raise ValueError(""Validation failed."")

                updates = []
                parameters = []

                if encrypted_email is not None:
                    updates.append(""email = ?"")
                    parameters.append(encrypted_email)

                if balance is not None:
                    updates.append(""balance = ?"")
                    parameters.append(balance)

                parameters.append(username)

                sql = f""UPDATE accounts SET {', '.join(updates)} WHERE username = ?""
                self.connection.execute(sql, parameters)
            except Exception as e:
                print(f""An error occurred: {e}"")

