import re

class Auditor:
    def __init__(self):
        self.log = []

    def log_entry(self, message):
        self.log.append(message)

class EmployeeManagementSystem:
    def __init__(self):
        self.employees = []
        self.auditor = Auditor()

    def add_profile(self, profile):
        employee_id = len(self.employees) + 1
        profile['id'] = employee_id
        self.employees.append(profile)
        job_titles = self.find_job_titles(profile['position'])
        if job_titles:
            self.auditor.log_entry(f""Employee ID {employee_id}: Job Titles Found - {job_titles}"")

    def find_job_titles(self, description):
        # Example pattern for common job titles
        job_title_patterns = [
            r'\bData Analyst\b', 
            r'\bSoftware Engineer\b',
            r'\bProject Manager\b'
        ]

        found_titles = []
        for pattern in job_title_patterns:
            if re.search(pattern, description, re.IGNORECASE):
                found_titles.append(re.findall(pattern, description, re.IGNORECASE)[0])

        return found_titles

    def get_audit_log(self):
        return self.auditor.log

# Usage
ems = EmployeeManagementSystem()

# Adding a new employee profile
ems.add_profile({
   'name': 'John Doe',
   'position': 'Data Analyst is the primary role of John Doe',
   'salary': 60000
})

# Display audit log
for entry in ems.get_audit_log():
    print(entry)
