from datetime import datetime

class File:
    def __init__(self, name, file_type, size, creation_date):
        self.name = name
        self.file_type = file_type
        self.size = size
        self.creation_date = creation_date

    def __str__(self):
        return f""Name: {self.name}, Type: {self.file_type}, Size: {self.size}KB, Creation Date: {self.creation_date}""

class FileManager:
    def __init__(self):
        self.files = []

    def add_file(self, file):
        if any(f.name == file.name for f in self.files):
            raise ValueError(""File with this name already exists."")
        self.files.append(file)

    def remove_file(self, file_name):
        for i, file in enumerate(self.files):
            if file.name == file_name:
                del self.files[i]
                return
        raise FileNotFoundError(""File not found."")

    def retrieve_file(self, file_name):
        for file in self.files:
            if file.name == file_name:
                return file
        raise FileNotFoundError(""File not found."")

    def display_files(self):
        for file in self.files:
            print(file)

    def sort_files_by_size(self):
        self.files.sort(key=lambda x: x.size)

    def sort_files_by_creation_date(self):
        self.files.sort(key=lambda x: x.creation_date)

# Example usage
if __name__ == ""__main__"":
    fm = FileManager()

    # Adding files
    try:
        fm.add_file(File(""file1.txt"", ""txt"", 150, datetime(2023, 5, 17)))
        fm.add_file(File(""file2.jpg"", ""jpg"", 2000, datetime(2023, 6, 10)))
        fm.add_file(File(""file3.mp4"", ""mp4"", 50000, datetime(2023, 7, 25)))
    except ValueError as e:
        print(e)

    # Display files
    fm.display_files()

    # Remove a file
    try:
        fm.remove_file(""file2.jpg"")
    except FileNotFoundError as e:
        print(e)

    # Retrieve a file
    try:
        retrieved = fm.retrieve_file(""file3.mp4"")
        print(f""Retrieved: {retrieved}"")
    except FileNotFoundError as e:
        print(e)

    # Sort by size and display
    fm.sort_files_by_size()
    print(""\nSorted by Size:"")
    fm.display_files()

    # Add another file to test sorting by creation date
    fm.add_file(File(""file4.docx"", ""docx"", 100, datetime(2023, 5, 20)))

    # Sort by creation date and display
    fm.sort_files_by_creation_date()
    print(""\nSorted by Creation Date:"")
    fm.display_files()
