from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory data storage for simplicity
resources = {
    '1': {'id': '1', 'name': 'Resource One', 'value': 100},
}

@app.route('/resource/<string:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id in resources:
        data = request.json
        resources[resource_id].update(data)
        return jsonify(resources[resource_id]), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

@app.route('/resource/<string:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if resource_id in resources:
        # Return the default settings after deletion
        default_settings = {'id': '', 'name': '', 'value': 0}
        del resources[resource_id]
        return jsonify(default_settings), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
