### Python: GameCharacter Class for Intelligent Attack Selection

```python
import time
import hashlib

class GameCharacter:
    def __init__(self):
        self.last_attack_time = 0
        self.cooldown_period = 2  # seconds

    def select_attack(self):
        current_time = time.time()
        if (current_time - self.last_attack_time) >= self.cooldown_period:
            return ""Attack selected""
        else:
            return ""Cooldown in effect, wait to attack""

    def update_last_attack_time(self):
        self.last_attack_time = time.time()

    @staticmethod
    def calculate_file_hash(file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    @staticmethod
    def service_status():
        # Example service status check
        return ""Service is running""

    @staticmethod
    def delay_between_actions_in_seconds():
        return 2

    @staticmethod
    def service_status_after_action(action):
        # Example of simulating a change in service status after an action
        if action == ""Attack"":
            return ""Service under attack""
        else:
            return ""No change in service""

# Example usage
character = GameCharacter()
print(character.select_attack())  # Output: Cooldown in effect, wait to attack

time.sleep(2)  # Simulate waiting time for cooldown

print(character.select_attack())  # Output: Attack selected
character.update_last_attack_time()

file_hash = character.calculate_file_hash('example.txt')
print(file_hash)
