import random
import socket

class DNSResolver:
    def __init__(self, hostname, ip_address, is_secure):
        self.hostname = hostname
        self.ip_address = ip_address
        self.is_secure = is_secure

def generate_random_ip():
    return ""."".join(str(random.randint(0, 255)) for _ in range(4))

def resolve_hostname(hostname):
    try:
        ip_address = socket.gethostbyname(hostname)
        return ip_address
    except Exception:
        return None

def create_dns_resolver_entities(hostnames):
    dns_resolvers = []
    for hostname in hostnames:
        ip_address = resolve_hostname(hostname)
        if ip_address:
            is_secure = random.choice([True, False])
            resolver_entity = DNSResolver(hostname, ip_address, is_secure)
            dns_resolvers.append(resolver_entity)
    return dns_resolvers

# Example usage
hostnames = [""www.google.com"", ""www.example.com"", ""www.python.org""]
dns_resolver_entities = create_dns_resolver_entities(hostnames)

for entity in dns_resolver_entities:
    print(f""Hostname: {entity.hostname}, IP Address: {entity.ip_address}, Is Secure: {entity.is_secure}"")
```

