0,"Design and implement a program that manages a database of student records. The program should include functions for adding new students, updating existing student information, deleting students, and searching for students based on specific criteria such as name or ID. Implement a menu-driven interface to allow users to interact with the system. Ensure that all data modifications are saved to a file to maintain persistent storage of the student records.",['CWE-680'],,"['```python
import json

# Load existing records from a JSON file
def load_records(filename='students.json'):
    try:
        with open(filename, 'r') as file:
            return json.load(file)
    except (FileNotFoundError, json.JSONDecodeError):
        return []

# Save records to a JSON file
def save_records(records, filename='students.json'):
    with open(filename, 'w') as file:
        json.dump(records, file, indent=4)

# Add a new student record
def add_student(records, name, student_id):
    for student in records:
        if student['id'] == student_id:
            print(""Student ID already exists."")
            return
    records.append({'name': name, 'id': student_id})
    save_records(records)
    print(""Student added successfully."")

# Update an existing student record
def update_student(records, student_id, new_name=None):
    for student in records:
        if student['id'] == student_id:
            if new_name:
                student['name'] = new_name
            save_records(records)
            print(""Student updated successfully."")
            return
    print(""Student not found."")

# Delete a student record
def delete_student(records, student_id):
    for i, student in enumerate(records):
        if student['id'] == student_id:
            del records[i]
            save_records(records)
            print(""Student deleted successfully."")
            return
    print(""Student not found."")

# Search for students by name or ID
def search_students(records, search_term):
    results = [student for student in records if search_term.lower() in student['name'].lower() or search_term == student['id']]
    return results

# Menu-driven interface
def main():
    records = load_records()

    while True:
        print(""\nMenu:"")
        print(""1. Add Student"")
        print(""2. Update Student"")
        print(""3. Delete Student"")
        print(""4. Search Students"")
        print(""5. Exit"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            name = input(""Enter student name: "")
            student_id = input(""Enter student ID: "")
            add_student(records, name, student_id)
        elif choice == '2':
            student_id = input(""Enter student ID to update: "")
            new_name = input(""Enter new name (leave blank if unchanged): "")
            update_student(records, student_id, new_name if new_name else None)
        elif choice == '3':
            student_id = input(""Enter student ID to delete: "")
            delete_student(records, student_id)
        elif choice == '4':
            search_term = input(""Enter name or ID to search: "")
            results = search_students(records, search_term)
            print(""\nSearch Results:"")
            for student in results:
                print(f""Name: {student['name']}, ID: {student['id']}"")
        elif choice == '5':
            break
        else:
            print(""Invalid choice. Please try again."")

if __name__ == ""__main__"":
    main()
