import json

class StudentDatabase:
    def __init__(self, filename='students.json'):
        self.filename = filename
        try:
            with open(self.filename, 'r') as file:
                self.students = json.load(file)
        except FileNotFoundError:
            self.students = {}

    def save_data(self):
        with open(self.filename, 'w') as file:
            json.dump(self.students, file)

    def add_student(self, student_id, name, age, grade):
        if student_id in self.students:
            print(""Student ID already exists."")
            return
        self.students[student_id] = {'name': name, 'age': age, 'grade': grade}
        self.save_data()

    def update_student(self, student_id, name=None, age=None, grade=None):
        if student_id not in self.students:
            print(""Student ID not found."")
            return
        if name:
            self.students[student_id]['name'] = name
        if age:
            self.students[student_id]['age'] = age
        if grade:
            self.students[student_id]['grade'] = grade
        self.save_data()

    def delete_student(self, student_id):
        if student_id in self.students:
            del self.students[student_id]
            self.save_data()
        else:
            print(""Student ID not found."")

    def search_students(self, **criteria):
        results = []
        for student_id, details in self.students.items():
            match = True
            for key, value in criteria.items():
                if details.get(key) != value:
                    match = False
                    break
            if match:
                results.append((student_id, details))
        return results

def menu():
