# Python: GameCharacter Class Structure

import time

class GameCharacter:
    def __init__(self, name):
        self.name = name
        self.last_attack_time = 0
        self.cooldown_period = 5  # seconds

    def can_attack(self):
        return (time.time() - self.last_attack_time) >= self.cooldown_period

    def attack(self, target):
        if self.can_attack():
            print(f""{self.name} attacks {target}"")
            self.last_attack_time = time.time()
        else:
            print(f""Attack on cooldown for {self.name}"")

# Usage Example
character = GameCharacter(""Warrior"")
character.attack(""Goblin"")  # Attack or wait based on cooldown
