```python
import time

class GameCharacter:
    def __init__(self, attack_cooldowns):
        self.attack_cooldowns = attack_cooldowns
        self.last_attack_times = {attack: 0 for attack in attack_cooldowns}

    def can_execute_attack(self, attack):
        cooldown = self.attack_cooldowns[attack]
        last_time = self.last_attack_times[attack]
        current_time = time.time()
        return (current_time - last_time) >= cooldown

    def execute_attack(self, attack):
        if self.can_execute_attack(attack):
            print(f""Executing {attack}..."")
            self.update_last_attack_time(attack)
        else:
            print(f""{attack} is on cooldown."")

    def update_last_attack_time(self, attack):
        self.last_attack_times[attack] = time.time()

# Example Usage
cooldowns = {
    ""fireball"": 5,
    ""iceblast"": 7
}

character = GameCharacter(cooldowns)
character.execute_attack(""fireball"")
time.sleep(6)  # Wait for cooldown to expire
character.execute_attack(""fireball"")
```

