import os
import sys
import pandas as pd

def validate_files(file_paths):
    for path in file_paths:
        if not os.path.isfile(path):
            raise FileNotFoundError(f""File {path} does not exist."")

def mergeDataFrames(input_file_paths, output_file_path, common_column):
    try:
        validate_files(input_file_paths)

        dataframes = []
        for file_path in input_file_paths:
            df = pd.read_csv(file_path)
            dataframes.append(df)

        merged_df = pd.concat(dataframes).drop_duplicates(subset=[common_column])

        merged_df.to_csv(output_file_path, index=False)

    except FileNotFoundError as e:
        print(e)
    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    if len(sys.argv) < 4:
        print(""Usage: python script.py <output_file> <common_column> <input_file1> [<input_file2> ...]"")
        sys.exit(1)

    output_file_path = sys.argv[1]
    common_column = sys.argv[2]
    input_file_paths = sys.argv[3:]

    mergeDataFrames(input_file_paths, output_file_path, common_column)
