class PDU:
    def __init__(self, tag, rnti, macHeader, crcTag):
        self.tag = tag
        self.rnti = rnti
        self.macHeader = macHeader
        self.crcTag = crcTag

def generate_random_tag():
    return random.randint(1000, 9999)

def generate_random_rnti():
    return random.randint(1, 65535)

def generate_random_mac_header():
    return bytes([random.randint(0, 255) for _ in range(8)])

def generate_random_crc_tag():
    return random.getrandbits(16)

def sendToWebSocket(pdu):
    pass

def checkPduIntegrity(pdu):
    return True

def handlePduInC(pdu):
    pass

def logPdu(pdu):
    print(f""Logged PDU: {pdu.__dict__}"")

def generateNfaapiPduList(count):
    pdu_list = []

    for _ in range(count):
        tag = generate_random_tag()
        rnti = generate_random_rnti()
        macHeader = generate_random_mac_header()
        crcTag = generate_random_crc_tag()

        pdu = PDU(tag, rnti, macHeader, crcTag)

        sendToWebSocket(pdu)

        if checkPduIntegrity(pdu):
            handlePduInC(pdu)
            logPdu(pdu)

        time.sleep(0.01)  # Wait for 10 milliseconds

        pdu_list.append(pdu)

    return pdu_list

