def generate_random_string(length=10):
    """"""Generate a secure, random string of given length.""""""
    return ''.join(random.choice(CHAR_SET) for _ in range(length))

def generate_snmpv3_security_contexts(num_contexts=5):
    """"""Generate SNMPv3 security contexts with random parameters.""""""
    security_contexts = []
    for _ in range(num_contexts):
        context = {
            'username': generate_random_string(),
            'authProtocol': random.choice(['SHA', 'MD5']),
            'privProtocol': random.choice(['AES', 'DES']),
            'authenticationPassword': generate_random_string(20),
        }
        security_contexts.append(context)
    return security_contexts

def run_grpc_tests(security_contexts):
    """"""Run gRPC tests using the generated SNMPv3 security contexts.""""""
    # Placeholder for actual gRPC test logic
