import threading
from datetime import datetime
import random
import string

class Component:
    def __init__(self, name, version, author, last_updated):
        self.name = name
        self.version = version
        self.author = author
        self.last_updated = last_updated

    def update(self, name=None, version=None, author=None, last_updated=None):
        if name is not None:
            self.name = name
        if version is not None:
            self.version = version
        if author is not None:
            self.author = author
        if last_updated is not None:
            self.last_updated = last_updated

class ComponentLibrary:
    def __init__(self):
        self.lock = threading.Lock()
        self.components = {}

    def add_component(self, component):
        with self.lock:
            if component.name in self.components:
                raise ValueError(f""Component {component.name} already exists."")
            self.components[component.name] = component

    def remove_component(self, name):
        with self.lock:
            if name not in self.components:
                raise KeyError(f""Component {name} does not exist."")
            del self.components[name]

    def update_component(self, name, **kwargs):
        with self.lock:
            if name not in self.components:
                raise KeyError(f""Component {name} does not exist."")
            component = self.components[name]
            component.update(**kwargs)

    def get_component(self, name):
        with self.lock:
            return self.components.get(name)

    def generate_random_component_data(self):
        random_name = ''.join(random.choices(string.ascii_letters, k=10))
        random_version = f""{random.randint(1, 9)}.{random.randint(0, 9)}.{random.randint(0, 9)}""
        random_author = ''.join(random.choices(string.ascii_letters + "" "", k=15)).strip()
        random_last_updated = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
        return Component(random_name, random_version, random_author, random_last_updated)

    def simulate_operations(self, rate_add=1, rate_remove=0.5):
        while True:
            action = random.choice(['add', 'remove'])
            component = self.generate_random_component_data()
            if action == 'add' and random.random() < rate_add:
                try:
                    self.add_component(component)
                    print(f""Added: {component.name}"")
                except ValueError as e:
                    print(e)
            elif action == 'remove' and random.random() < rate_remove:
                name = ''.join(random.choices(string.ascii_letters, k=10))
                try:
                    self.remove_component(name)
                    print(f""Removed: {name}"")
                except KeyError as e:
                    print(e)

# Example Usage
library = ComponentLibrary()
threading.Thread(target=library.simulate_operations, args=(0.7, 0.3)).start()
```

