0,"Create a Python script that encrypts a JSON Web Token (JWT) using a symmetric encryption algorithm and a secret key. The script should generate the JWT with an optional expiration timestamp and include the encrypted payload data. It should also provide a function to decrypt the JWT using the same secret key and return the original payload data in its original format. The script should use standard libraries for JWT generation and decryption, and it should handle potential errors such as invalid secret keys or expired tokens gracefully, providing appropriate error messages.",['CWE-120'],,"['```python
import jwt
import datetime
from typing import Dict, Optional

def create_jwt(payload: Dict, secret_key: str, expiration_seconds: Optional[int] = None) -> str:
    try:
        # Set expiration if provided
        if expiration_seconds:
            payload['exp'] = datetime.datetime.utcnow() + datetime.timedelta(seconds=expiration_seconds)

        # Encode the JWT with symmetric encryption (HS256)
        token = jwt.encode(payload, secret_key, algorithm='HS256')
        return token
    except Exception as e:
        raise ValueError(f""Error creating JWT: {str(e)}"")

def decode_jwt(token: str, secret_key: str) -> Dict:
    try:
        # Decode the JWT and verify it using the same symmetric key
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        return payload
    except jwt.ExpiredSignatureError:
        raise ValueError(""Token has expired"")
    except jwt.InvalidTokenError as e:
        raise ValueError(f""Invalid token: {str(e)}"")

# Example usage
if __name__ == ""__main__"":
    secret = ""your-very-secret-key""
    data = {""user_id"": 123, ""role"": ""admin""}

    # Create a JWT with an expiration of 60 seconds from now
    jwt_token = create_jwt(data, secret, expiration_seconds=60)
    print(""JWT Token:"", jwt_token)

    try:
