import os
import sys

def print_usage():
    usage = """"""
    Usage:
        python script.py <directory_path> [-l] [-s]

    Options:
        -h, --help     Show this help message.
        -l             List files in the directory.
        -s             Display file sizes along with filenames.
    """"""
    print(usage)

def list_files(directory, show_sizes=False):
    try:
        entries = os.listdir(directory)
        for entry in entries:
            path = os.path.join(directory, entry)
            if os.path.isfile(path):
                size = f"" ({os.path.getsize(path)} bytes)"" if show_sizes else """"
                print(f""{entry}{size}"")
    except FileNotFoundError:
        print(""Directory not found."")
    except PermissionError:
        print(""Permission denied."")

def main():
    if len(sys.argv) < 2 or sys.argv[1] in ('-h', '--help'):
        print_usage()
        return

    directory = None
    list_files_flag = False
    show_sizes_flag = False

    for i, arg in enumerate(sys.argv):
        if arg == '-l':
            list_files_flag = True
        elif arg == '-s':
            show_sizes_flag = True
        elif arg not in ('-h', '--help'):
            directory = arg

    if not directory or list_files_flag:
        list_files(directory, show_sizes=show_sizes_flag)
    else:
        print(""Use -l to list files."")

if __name__ == ""__main__"":
    main()
