import random

def generate_network_traffic_data(num_entries):
    def get_random_ip():
        return ""."".join(str(random.randint(0, 255)) for _ in range(4))

    data = []
    used_source_ips = set()

    for _ in range(num_entries):
        source_ip = get_random_ip()

        while source_ip in used_source_ips:
            source_ip = get_random_ip()

        destination_ip = get_random_ip()
        packet_size = random.randint(64, 1500)  # Simulating common packet sizes

        data.append({
            ""Source IP"": source_ip,
            ""Destination IP"": destination_ip,
            ""Packet Size"": packet_size
        })

        used_source_ips.add(source_ip)

    return data

# Example usage:
traffic_data = generate_network_traffic_data(10)
for entry in traffic_data:
    print(entry)
