import threading
import random
from datetime import date
import re

class UserProfile:
    def __init__(self, username, email, dob, bio):
        self.username = username
        self.email = email
        self.dob = dob
        self.bio = bio

    def update_profile(self, **kwargs):
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)

class ProfileManager:
    def __init__(self):
        self.profiles = {}
        self.lock = threading.Lock()

    def _is_valid_email(self, email):
        return re.match(r""[^@]+@[^@]+\.[^@]+"", email) is not None

    def create_profile(self, username, email, dob=None, bio=''):
        with self.lock:
            if username in self.profiles:
                raise ValueError(""Username already exists."")

            if not self._is_valid_email(email):
                raise ValueError(""Invalid email format."")

            profile = UserProfile(username, email, dob or date.today(), bio)
            self.profiles[username] = profile
        return profile

    def modify_profile(self, username, **kwargs):
        with self.lock:
            if username not in self.profiles:
                raise KeyError(""Profile not found."")

            profile = self.profiles[username]
            profile.update_profile(**kwargs)

    def delete_profile(self, username):
        with self.lock:
            if username not in self.profiles:
                raise KeyError(""Profile not found."")

            del self.profiles[username]

    def get_profile(self, username):
        with self.lock:
            return self.profiles.get(username)

    @staticmethod
    def generate_random_username():
        chars = ""abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789""
        return ''.join(random.choice(chars) for _ in range(8))

    @staticmethod
    def generate_random_email():
        domains = [""example.com"", ""mail.com"", ""test.org""]
        return f""user_{random.randint(100, 999)}@{random.choice(domains)}""

    @staticmethod
    def generate_random_dob(years_range=(18, 60)):
        start_year = date.today().year - years_range[1]
        end_year = date.today().year - years_range[0]
        year = random.randint(start_year, end_year)
        month = random.randint(1, 12)
        day = random.randint(1, 28) # Simplification to avoid handling different days in months
        return date(year, month, day)

    @staticmethod
    def generate_random_bio():
        bios = [
            ""Loves hiking and outdoor adventures."",
            ""Passionate about technology and innovation."",
            ""Art enthusiast and aspiring painter.""
        ]
        return random.choice(bios)

class DynamicConfig:
    def __init__(self):
        self.config = {
            'create_rate': 1,
