import json
import logging

class JsonParser:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        self.registry[id] = factory_func

    def create_instance(self, id, data):
        factory_func = self.registry.get(id)
        if not factory_func:
            raise ValueError(f""No factory function registered for ID: {id}"")
        return factory_func(data)

    def to_json_string(self, data):
        return json.dumps(data)

    def from_json_string(self, json_str):
        return json.loads(json_str)

class CustomObject:
    pass

def create_custom_object(data):
    obj = CustomObject()
    obj.custom_attribute = data
    return obj

def validate_data(data):
    if not isinstance(data, dict) or 'key' not in data or 'value' not in data:
        raise ValueError(""Invalid data structure. Must be a dictionary with keys 'key' and 'value'."")

def log_action(action_type, action_id, status):
    log_msg = f""{action_type} - ID: {action_id} - Status: {status}""
    logging.info(log_msg)

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)

json_parser = JsonParser()
json_parser.add_factory('custom', create_custom_object)
data_to_json = {'key': 'value'}
validate_data(data_to_json)
json_str = json_parser.to_json_string(data_to_json)
log_action(""Data to JSON"", ""12345"", ""Success"")

# Assume that the data structure for CustomObject creation is a dictionary
loaded_data = json_parser.from_json_string(json_str)

# Create an instance using the custom factory with loaded JSON data
new_instance = json_parser.create_instance('custom', loaded_data)
log_action(""Create Instance"", ""12345"", ""Success"")
