class CustomArrayModifier:
    def __init__(self, array):
        if not isinstance(array, list) or not all(isinstance(x, int) for x in array):
            raise ValueError(""Input must be a list of integers."")

        self.array = array

    def RemoveDuplicates(self):
        if len(self.array) == 0:
            raise ValueError(""Array cannot be empty when removing duplicates."")

        seen = set()
        result = []
        for item in self.array:
            if item not in seen:
                seen.add(item)
                result.append(item)

        self.array = result

    def ReplaceOutOfRangeValues(self, min_value, max_value, default=0):
        if min_value >= max_value:
            raise ValueError(""Minimum value must be less than maximum value."")

        if len(self.array) == 0:
            raise ValueError(""Array cannot be empty when replacing out of range values."")

        self.array = [
            x if min_value <= x <= max_value else default
            for x in self.array
        ]

    def EnsureUniqueSum(self):
        if len(self.array) == 0:
            raise ValueError(""Array cannot be empty when ensuring unique sum."")

        seen = set()
        result = []
        for value in self.array:
            new_value = value
            while new_value in seen:
                new_value += 1  # Increment to make it unique

            seen.add(new_value)
            result.append(new_value)

        self.array = result
