0,"Create a new program that manages a collection of tasks in a to-do list application. The program should enable users to add, delete, and retrieve tasks from the list. Each task should have attributes such as title, description, due date, and priority level. Implement a method to display all tasks in the list in an organized format. Additionally, provide functionality to sort the tasks based on their due date or priority level. Ensure proper error handling for scenarios like attempting to remove a non-existent task or adding duplicate tasks with identical titles and descriptions.",['CWE-323'],,"['```python
from datetime import datetime

class Task:
    def __init__(self, title, description, due_date, priority):
        self.title = title
        self.description = description
        self.due_date = datetime.strptime(due_date, '%Y-%m-%d')
        self.priority = priority

    def __str__(self):
        return f""Title: {self.title}\nDescription: {self.description}\nDue Date: {self.due_date.date()}\nPriority: {self.priority}""

class ToDoList:
    def __init__(self):
        self.tasks = []

    def add_task(self, title, description, due_date, priority):
        for task in self.tasks:
            if task.title == title and task.description == description:
                raise ValueError(""Task with the same title and description already exists."")

        new_task = Task(title, description, due_date, priority)
        self.tasks.append(new_task)

    def delete_task(self, title):
        for i, task in enumerate(self.tasks):
            if task.title == title:
                del self.tasks[i]
                return
        raise ValueError(""Task not found."")

    def retrieve_tasks(self):
        return [task.__str__() for task in self.tasks]

    def display_all_tasks(self):
        for task in sorted(self.tasks, key=lambda x: (x.due_date, x.priority)):
            print(task)

    def sort_tasks_by_due_date(self):
        self.tasks.sort(key=lambda x: x.due_date)

    def sort_tasks_by_priority(self):
        self.tasks.sort(key=lambda x: x.priority)

# Example usage
if __name__ == ""__main__"":
    todo_list = ToDoList()
    try:
        todo_list.add_task(""Task 1"", ""Description of task 1"", ""2023-11-01"", 2)
        todo_list.add_task(""Task 2"", ""Description of task 2"", ""2023-10-15"", 1)

        print(""\nAll tasks sorted by due date:"")
        todo_list.sort_tasks_by_due_date()
        todo_list.display_all_tasks()

        print(""\nAll tasks sorted by priority:"")
        todo_list.sort_tasks_by_priority()
        todo_list.display_all_tasks()

    except ValueError as e:
        print(e)
