import json
import xml.etree.ElementTree as ET
from collections import defaultdict

def process_json_to_xml(json_file_path, xml_output_path, namespace=None, preserve_comments=False, process_special_keys=False):
    try:
        with open(json_file_path, 'r') as file:
            json_data = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f""Invalid JSON file or path: {e}"")

    root = ET.Element('root')
    transform_json_to_xml(json_data, root, namespace=namespace)

    if preserve_comments:
        preserve_comments_in_xml(root)

    if process_special_keys:
        process_special_keys_in_json(root)

    tree = ET.ElementTree(root)
    tree.write(xml_output_path)

def transform_json_to_xml(data, parent_element, namespace=None):
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, (dict, list)):
                child_element = ET.SubElement(parent_element, key)
                transform_json_to_xml(value, child_element)
            else:
                tag = key.replace('_', ' ').title()
                if namespace and ':' in tag and not tag.startswith('xmlns'):
                    tag = f""{namespace}{' '.join(tag.split())}""
                elif namespace and not tag.startswith('xmlns'):
                    tag = f""{namespace}:{tag}""
                element = ET.SubElement(parent_element, tag)
                element.text = str(value)
    elif isinstance(data, list):
        for item in data:
            transform_json_to_xml(item, parent_element)

def preserve_comments_in_xml(element):
    if element.text is not None and '<' not in element.text and '>' not in element.text:
        comment_text = ''.join([c.tail for c in element.getchildren()])
        if comment_text.strip():
            comment_node = ET.Comment(comment_text.strip())
            comment_node.tail = '\n'
            element.insert(0, comment_node)

def process_special_keys_in_json(element):
    special_keys_mapping = {
        'id': 'ID',
        'status': 'Status',
        'date': 'Date',
        'time': 'Time'
    }

    for child in list(element):
        key = child.tag.split('}')[-1]  # Handle namespace properly
        original_key_value = child.attrib.get(key, None)

        if key in special_keys_mapping:
            mapped_key = special_keys_mapping[key]

            if original_key_value is not None and '-' in original_key_value:
                mapped_key_value_parts = original_key_value.split('-')

                while len(mapped_key_value_parts) > 1:
                    mapped_key_value_parts[0] = mapped_key + '_' + mapped_key_value_parts[0]
                    mapped_key_value_parts.pop()

                child.tag = mapped_key
                child.attrib[mapped_key] = '-'.join(mapped_key_value_parts)
            else:
                child.tag = mapped_key
