            src_char, _, tgt_char = rule
            if tgt_char == 'Z':
                rule_map[ord('\n')] = ord(src_char)
            else:
                rule_map[ord(src_char)] = ord(tgt_char)

    # Apply the compression rules to the data
    compressed_data = bytearray()
    i = 0
    while i < len(data):
        if data[i] in rule_map and (data[i] != ord('\n') or rule_map[data[i]] != ord(src_char)):
            compressed_data.append(rule_map[data[i]])
            if data[i] == ord('\n'):
                # Handle newline compression carefully
                i += 1
                while i < len(data) and data[i] == ord('\n'):
                    i += 1
                continue
        else:
            compressed_data.append(data[i])
        i += 1

    return bytes(compressed_data)

def decompressData(data: bytes, compressionRules: str) -> bytes:
    # Create a reverse dictionary for the replacement rules
    reverse_rule_map = {}

    for rule in compressionRules.split(','):
        if len(rule) == 3:
            src_char, _, tgt_char = rule
            reverse_key = ord(src_char)
            if tgt_char == 'Z':
                reverse_rule_map[ord('\n')] = reverse_key
            else:
                reverse_rule_map[ord(tgt_char)] = reverse_key

    # Apply the decompression rules to the data
    decompressed_data = bytearray()

    i = 0
    while i < len(data):
        if data[i] in reverse_rule_map:
            decompressed_data.append(reverse_rule_map[data[i]])
        else:
            decompressed_data.append(data[i])
        i += 1

    return bytes(decompressed_data)

def compressAndUncompressData(inputFilePath: str, outputFilePath: str, compressionRules: str):
    # Read the input file
    with open(inputFilePath, 'rb') as inputFile:
        original_data = inputFile.read()

    # Compress the data
    compressed_data = compressData(original_data, compressionRules)

    # Write the compressed data to the output file
    with open(outputFilePath, 'wb') as outputFile:
        outputFile.write(compressed_data)

def verifyCorrectness(inputFilePath: str, outputFilePath: str, compressionRules: str) -> bool:
    # Read original and compressed files
    with open(inputFilePath, 'rb') as inputFile:
        original_data = inputFile.read()

    with open(outputFilePath, 'rb') as outputFile:
        compressed_data = outputFile.read()

    # Decompress the data
    decompressed_data = decompressData(compressed_data, compressionRules)

    # Verify no data loss and check file sizes for basic correctness
    return original_data == decompressed_data

